document.addEventListener(`click`,e=>{let t=e.target.closest(`[data-help-type]`);if(!t)return;let n=document.getElementById(`issueTypeSelect`);if(!n)return;let r=t.dataset.helpType;document.querySelectorAll(`[data-help-type]`).forEach(e=>{e.classList.remove(`is-selected`),e.setAttribute(`aria-pressed`,`false`)});for(let e of n.options)if(e.value.trim().toLowerCase()===r.trim().toLowerCase()||e.textContent.trim().toLowerCase()===r.trim().toLowerCase()){e.selected=!0,t.classList.add(`is-selected`),t.setAttribute(`aria-pressed`,`true`);break}document.getElementById(`form`)?.scrollIntoView({behavior:`smooth`,block:`start`})});